:host {
    display: block;
}

.channel-details-dialog {
    max-height: min(78vh, 720px);
}

.dialog-description {
    margin: 0 0 20px;
    color: var(--mat-sys-on-surface-variant);
}

.details-section + .details-section {
    margin-top: 24px;
    padding-top: 20px;
    border-top: 1px solid var(--mat-sys-outline-variant);
}

.section-title {
    margin: 0 0 12px;
    font-size: 0.92rem;
    font-weight: 600;
    line-height: 1.3;
}

.details-grid {
    display: grid;
    gap: 12px;
    margin: 0;
}

.detail-row {
    display: grid;
    grid-template-columns: minmax(140px, 180px) minmax(0, 1fr);
    gap: 6px 16px;
    align-items: start;
}

dt {
    margin: 0;
    color: var(--mat-sys-on-surface-variant);
    font-weight: 600;
}

dd {
    margin: 0;
    min-width: 0;
    line-height: 1.45;

    &.empty {
        color: var(--mat-sys-on-surface-variant);
        font-style: italic;
    }

    &.monospace {
        font-family:
            ui-monospace,
            SFMono-Regular,
            Menlo,
            Monaco,
            Consolas,
            'Liberation Mono',
            'Courier New',
            monospace;
        font-size: 0.92em;
    }

    &.wrap {
        overflow-wrap: anywhere;
        word-break: break-word;
    }
}

@media (max-width: 640px) {
    .detail-row {
        grid-template-columns: minmax(0, 1fr);
        gap: 4px;
    }
}

