:host {
    display: block;
    color: var(--app-body-color, var(--mat-sys-on-surface));
}

// ─── Hero header ────────────────────────────────────────────────────────────
.channel-dialog__hero {
    margin: 0;
    padding: 20px 20px 18px;
    display: grid;
    gap: 18px;
    background:
        var(--app-accent-gradient),
        var(--app-widget-header-bg, var(--mat-sys-surface-container-high));
    border-bottom: 1px solid var(--app-widget-header-border, rgba(255, 255, 255, 0.05));
}

.channel-dialog__hero-copy {
    display: grid;
    gap: 10px;
}

.channel-dialog__eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    margin: 0;
    color: var(--app-eyebrow-color, var(--mat-sys-on-surface-variant));
    font-size: 0.72rem;
    font-weight: 600;
    letter-spacing: 0.1em;
    text-transform: uppercase;
}

.channel-dialog__eyebrow-mark {
    width: 8px;
    height: 8px;
    border-radius: 999px;
    background: var(--mat-sys-primary);
    box-shadow: 0 0 0 4px color-mix(in srgb, var(--mat-sys-primary) 14%, transparent);
}

.channel-dialog__headline-row {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 14px;
}

.channel-dialog__headline-text {
    display: flex;
    align-items: center;
    gap: 14px;
    min-width: 0;
}

.channel-dialog__logo {
    width: 48px;
    height: 48px;
    border-radius: 12px;
    object-fit: contain;
    background: var(--mat-sys-surface-container);
    border: 1px solid var(--app-separator);
    flex-shrink: 0;
}

