1	import { ComponentFixture, TestBed } from '@angular/core/testing';
2	import { NoopAnimationsModule } from '@angular/platform-browser/animations';
3	import { MAT_DIALOG_DATA } from '@angular/material/dialog';
4	import { TranslateModule } from '@ngx-translate/core';
5	import { Channel } from 'shared-interfaces';
6	import { ChannelDetailsDialogComponent } from './channel-details-dialog.component';
7	
8	describe('ChannelDetailsDialogComponent', () => {
9	    let fixture: ComponentFixture<ChannelDetailsDialogComponent>;
10	    let component: ChannelDetailsDialogComponent;
11	
12	    const channel: Channel = {
13	        epgParams: 'src=test-playlist',
14	        group: {
15	            title: 'News',
16	        },
17	        http: {
18	            origin: 'https://provider.example.com',
19	            referrer: 'https://provider.example.com/list',
20	            'user-agent': 'IPTVnator Test',
21	        },
22	        id: 'channel-1',
23	        name: 'News One',
24	        radio: 'false',
25	        tvg: {
26	            id: 'news-one',
27	            logo: 'https://provider.example.com/logo.png',
28	            name: 'News One HD',
29	            rec: '5',
30	            url: 'https://provider.example.com/guide.xml',
31	        },
32	        url: 'https://provider.example.com/stream.m3u8',
33	        catchup: {
34	            days: '5',
35	            source: 'https://provider.example.com/catchup.m3u8',
36	            type: 'append',
37	        },
38	        timeshift: '5',
39	    };
40	
41	    beforeEach(async () => {
42	        await TestBed.configureTestingModule({
43	            imports: [
44	                ChannelDetailsDialogComponent,
45	                NoopAnimationsModule,
46	                TranslateModule.forRoot(),
47	            ],
48	            providers: [
49	                {
50	                    provide: MAT_DIALOG_DATA,
51	                    useValue: channel,
52	                },
53	            ],
54	        }).compileComponents();
55	
56	        fixture = TestBed.createComponent(ChannelDetailsDialogComponent);
57	        component = fixture.componentInstance;
58	        fixture.detectChanges();
59	    });
60	
61	    it('derives archive window and playback support from parsed catchup metadata', () => {
62	        expect(component.archiveDays).toBe(5);
63	        expect(component.catchupAvailable).toBe(true);
64	        expect(component.catchupPlaybackSupported).toBe(true);
65	        expect(component.summaryFields).toEqual(
66	            expect.arrayContaining([
